      "请由多智能体协作评审一份改动。假设改动内容为下面这段产品上线公告的开头，若我随后提供真实改动，则以我提供的为准：\n“我们很高兴地宣布，新版团队协作工具正式上线。本次更新包含任务看板、文件共享、消息提醒和权限管理四项功能，欢迎体验。”\n请让各智能体先各自独立阅读，不互相参考；然后每人只说出“最该改的一处”及理由，重点判断是否过于功能罗列、缺少用户场景和价值主张。汇总时保留分歧，按优先级整理修改建议，最后给出明确结论。输出为简洁评审纪要，完成后请询问我是否需要细化到具体句子或形成修改清单。",
