    iaStartSubtitle: "Talk to an agent directly, or pull a team together.",
    iaStartSubtitleDirect: "Pick an agent for this job; if unsure, Manager is the generalist that takes anything on.",
    iaStartSubtitleRooms: "Pull a team together — here Manager is the coordinator, breaking work down and driving it.",
    iaStartSend: "Send",
    iaComposerTip: "Enter to send · Shift + Enter for a new line",
    iaStartExample_members_title: "List workspace members and responsibilities",
    iaStartExample_members_hint: "Members, roles, and responsibilities at a glance",
    iaStartExample_members_prompt:
      "List all members of the current collaboration workspace in a table with each member's name, role, and responsibilities. Mark missing information as “Not specified”; do not guess or invent details. When finished, ask whether I would like the members grouped by responsibility or contact details and assignments added.",
    iaStartExample_research_title: "Research real-world Agent adoption",
    iaStartExample_research_hint: "Research in parallel and merge sourced findings",
    iaStartExample_research_prompt:
      "Have multiple agents collaborate on a research task. Use “Enterprise AI Agent adoption over the past year” as the example topic unless I provide a different topic later.\nDivide the work yourselves into at least three parallel research tracks:\n1. Products and vendors: mainstream enterprise Agent products, key releases, and timelines;\n2. Industry cases and business value: typical use cases, efficiency gains, or cost figures;\n3. Technical challenges and risks: reliability, permissions, data security, evaluation, and operations.\nEach track should organize key facts, figures, and dates with source links or references. Then have one agent consolidate the findings into a report that distinguishes facts from inferences, flags conflicting information, and invents nothing. When finished, ask whether I would like to adjust the topic, time range, or report length.",
    iaStartExample_review_title: "Review a launch announcement",
    iaStartExample_review_hint: "Independent reviews, disagreements, and a clear verdict",
    iaStartExample_review_prompt:
      "Have multiple agents collaborate on reviewing a change. Use the following opening of a product launch announcement as the example change unless I provide an actual change later:\n“We are pleased to announce the launch of our new team collaboration tool. This release includes four features: task boards, file sharing, message notifications, and access management. Give it a try.”\nHave each agent first read it independently without consulting the others, then identify only the single change most worth making and explain why. Focus on whether it lists features excessively while lacking user scenarios and a value proposition. Preserve disagreements when consolidating the reviews, prioritize the recommendations, and give a clear verdict. Deliver concise review notes, then ask whether I would like sentence-level suggestions or an actionable revision checklist.",
