    iaStartExample_knowledgeCard_title: "Turn materials into a visual knowledge card",
    iaStartExample_knowledgeCard_hint: "A scrapbook-style, single-page HTML explainer",
    iaStartExample_knowledgeCard_prompt:
      "Turn the materials I provide into a clear, approachable visual knowledge card delivered as a single HTML page. Use a scrapbook-style layout with prominent annotations and compact sections so readers can quickly grasp the key points. If I have not provided materials yet, use “Coffee brewing basics” as an example: compare how grind size, water temperature, and extraction time affect flavor, and include corresponding parameters and brewing tips. Add sticky-note-style borders and clearly label the content “Example”. When finished, ask what kind of materials I would like to organize and which illustration style I prefer, and remind me that I can paste or upload materials directly.",
    iaStartExample_meetingNotes_title: "Write a project meeting notes template",
    iaStartExample_meetingNotes_hint: "Polished Markdown with clear decisions and action items",
    iaStartExample_meetingNotes_prompt:
      "Write a ready-to-use project meeting notes template in polished Markdown. Include exactly five sections: meeting summary, key discussions, trade-offs, decisions, and action items. If meeting records are provided, organize them strictly from the source without inventing or adding details; mark owners, deadlines, and other missing information as “Not specified”. If no records are provided, show the blank template first, followed by a compact fictional example in a blockquote prominently labeled “Example”, using a “Release retrospective” scenario. Emphasize key conclusions and present action items in a table with the task, owner, and deadline. When finished, invite me to provide meeting records and mention that I can paste or upload them directly.",
    iaStartExample_aiTrends_title: "Create an AI trends briefing presentation",
    iaStartExample_aiTrends_hint: "An HTML briefing covering six areas over the past 12 months",
    iaStartExample_aiTrends_prompt:
      "Act as an industry research analyst and create an HTML presentation on “AI trends over the past year” for industry research and management briefings. Search the web for public information from the 12 months leading up to the execution date, covering six areas: Agents, multimodal AI, on-device AI, embodied AI, AI coding, and computing chips.",
